function getDashboardProjects(){const query=(document.getElementById('dashboardProjectSearch')?.value||'').trim().toLocaleLowerCase('th'),status=document.getElementById('dashboardStatusFilter')?.value||'',province=document.getElementById('dashboardProvinceFilter')?.value||'',district=document.getElementById('dashboardDistrictFilter')?.value||'',subdistrict=document.getElementById('dashboardSubdistrictFilter')?.value||'';return projects.filter(project=>(!query||project.name.toLocaleLowerCase('th').includes(query))&&(!status||project.status===status)&&(!province||project.province===province)&&(!district||project.district===district)&&(!subdistrict||project.village===subdistrict))}
