  let authAdvanceTimer;
  function showAuthPhoto(index){clearTimeout(authAdvanceTimer);const targetIndex=(index+authForestPhotos.length)%authForestPhotos.length,nextSlot=activeAuthSlot===0?1:0,candidate=nextSlot===0?video:videoAlt,previous=activeAuthSlot===0?video:videoAlt,item=authForestPhotos[targetIndex];let activated=false;credit.href=item.href;credit.textContent=`${item.caption} · ${item.credit}`;if(candidate.dataset.photo!==item.video){candidate.dataset.photo=item.video;candidate.src=item.video;candidate.load()}const activate=()=>{if(activated)return;activated=true;candidate.removeEventListener('canplay',activate);candidate.removeEventListener('error',failed);candidate.play().catch(()=>{});candidate.classList.add('is-active');previous.classList.remove('is-active');activeAuthSlot=nextSlot;authPhotoIndex=targetIndex;window.setTimeout(()=>{previous.pause();const preloadIndex=(targetIndex+1)%authForestPhotos.length;previous.dataset.photo=authForestPhotos[preloadIndex].video;previous.src=authForestPhotos[preloadIndex].video;previous.load()},750);authAdvanceTimer=window.setTimeout(()=>showAuthPhoto(authPhotoIndex+1),4000)};const failed=()=>{candidate.removeEventListener('canplay',activate);authAdvanceTimer=window.setTimeout(()=>showAuthPhoto(targetIndex+1),900)};candidate.addEventListener('canplay',activate);candidate.addEventListener('error',failed,{once:true});if(candidate.readyState>=3)activate()}
