function readAuthUsers(){try{const users=JSON.parse(localStorage.getItem(AUTH_USERS_KEY)||'[]');return Array.isArray(users)?users:[]}catch{return[]}}
function showAuthError(id,message){const box=document.getElementById(id);box.textContent=message;box.hidden=false}
function clearAuthError(id){const box=document.getElementById(id);box.textContent='';box.hidden=true}
function encodeBytes(bytes){return btoa(Array.from(bytes,byte=>String.fromCharCode(byte)).join(''))}
async function hashDemoPassword(password,salt){if(!crypto.subtle)throw new Error('เบราว์เซอร์นี้ไม่รองรับ กรุณาเปิดผ่าน localhost หรือ HTTPS');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},key,256);return encodeBytes(new Uint8Array(bits))}
function enterDemo(firstRegistration=false){
  const userId=sessionStorage.getItem('carbonlens-auth-session')||localStorage.getItem('carbonlens-auth-remember'),user=readAuthUsers().find(item=>item.id===userId);
  if(!user){sessionStorage.removeItem('carbonlens-auth-session');localStorage.removeItem('carbonlens-auth-remember');return}
  guestMode=false;appShell.classList.remove('guest-mode');document.getElementById('guestHeaderButton')?.remove();document.getElementById('guestModePill')?.remove();activeUserId=user.id;onboardingRequired=firstRegistration||localStorage.getItem(`carbonlens-onboarding-pending-${user.id}`)==='true';
  const storedProjects=localStorage.getItem(`${KEY}:${user.id}`);if(firstRegistration){projects=[];localStorage.setItem(`${KEY}:${user.id}`,'[]')}else if(storedProjects){try{projects=JSON.parse(storedProjects)}catch{projects=[]}}else{projects=[];localStorage.setItem(`${KEY}:${user.id}`,'[]')}
  const parts=user.name.trim().split(/\s+/),firstName=user.firstName||parts.shift()||'',lastName=user.lastName||parts.join(' '),safeName=escapeHtml(user.name),initials=user.name.trim().split(/\s+/).slice(0,2).map(part=>Array.from(part)[0]||'').join('').toLocaleUpperCase('th-TH');
  const greeting=document.querySelector('#page-dashboard .page-heading h1'),profileName=document.querySelector('.profile-identity span:nth-child(2) b'),profileEmail=document.querySelector('.profile-identity span:nth-child(2) small'),profileAvatar=document.querySelector('.profile-avatar'),topAvatar=document.querySelector('.top-avatar');
  if(greeting)greeting.innerHTML=`สวัสดีค่ะ, คุณ${safeName} <span class="wave">✳</span>`;
  if(profileName)profileName.textContent=user.name;if(profileEmail)profileEmail.textContent=user.email;if(profileAvatar)profileAvatar.textContent=initials;
  if(topAvatar){topAvatar.textContent=initials;topAvatar.title=`เปิดโปรไฟล์ของ ${user.name}`;topAvatar.setAttribute('aria-label',`เปิดโปรไฟล์ของ ${user.name}`)}
  document.getElementById('profilePageName').textContent=user.name;document.getElementById('profilePageEmail').textContent=user.email;document.getElementById('profileDetailEmail').textContent=user.email;document.getElementById('profileFirstName').textContent=firstName;document.getElementById('profileLastName').textContent=lastName;document.getElementById('profilePageAvatar').textContent=initials;
  loginScreen.hidden=true;appShell.hidden=false;renderProjects();renderDashboard();renderParcelProjects();go(onboardingRequired?'projects':'dashboard');if(onboardingRequired)openProjectForm()
}
if(sessionStorage.getItem('carbonlens-auth-session')||localStorage.getItem('carbonlens-auth-remember'))enterDemo();
const guestButton=document.createElement('button');guestButton.type='button';guestButton.className='guest-entry';guestButton.textContent='เยี่ยมชมตัวอย่างโดยไม่เข้าสู่ระบบ';guestButton.addEventListener('click',()=>{guestMode=true;onboardingRequired=false;activeUserId='';projects=structuredClone(DEMO_DATA.projects);renderDashboard();loginScreen.hidden=true;appShell.hidden=false;appShell.classList.add('guest-mode');go('dashboard');const headerButton=document.createElement('button');headerButton.type='button';headerButton.id='guestHeaderButton';headerButton.className='guest-login-button';headerButton.textContent='เข้าสู่ระบบ';headerButton.addEventListener('click',exitGuest);document.querySelector('.top-actions').prepend(headerButton);const profileButton=document.getElementById('profileButton');if(profileButton){profileButton.textContent='👀';profileButton.title='โหมดเยี่ยมชม';profileButton.setAttribute('aria-label','โหมดเยี่ยมชม')}});document.getElementById('loginForm').insertBefore(guestButton,document.querySelector('#loginForm .login-demo'));
guestButton.addEventListener('click',()=>{const greeting=document.querySelector('#page-dashboard .page-heading h1'),profileName=document.querySelector('.profile-identity span:nth-child(2) b'),profileEmail=document.querySelector('.profile-identity span:nth-child(2) small'),pill=document.createElement('span');pill.id='guestModePill';pill.className='guest-mode-pill';pill.textContent='โหมดเยี่ยมชม';document.querySelector('.top-actions').prepend(pill);if(greeting)greeting.innerHTML='สวัสดีค่ะ, ผู้เยี่ยมชม <span class="wave">✳</span>';if(profileName)profileName.textContent='ผู้เยี่ยมชม';if(profileEmail)profileEmail.textContent='เข้าชมแบบอ่านอย่างเดียว'});
