document.getElementById('loginForm').addEventListener('submit',async e=>{e.preventDefault();clearAuthError('loginError');if(!e.currentTarget.reportValidity())return;const email=document.getElementById('loginUser').value.trim().toLowerCase(),password=document.getElementById('loginPassword').value,user=readAuthUsers().find(item=>item.email===email);try{if(!user||await hashDemoPassword(password,Uint8Array.from(atob(user.salt),c=>c.charCodeAt(0)))!==user.passwordHash)throw new Error('อีเมลหรือรหัสผ่านไม่ถูกต้อง');sessionStorage.setItem('carbonlens-auth-session',user.id);if(document.getElementById('rememberLogin').checked)localStorage.setItem('carbonlens-auth-remember',user.id);else localStorage.removeItem('carbonlens-auth-remember');enterDemo()}catch(error){showAuthError('loginError',error.message||'ไม่สามารถเข้าสู่ระบบได้')}});
document.getElementById('registerForm').addEventListener('submit',async e=>{e.preventDefault();clearAuthError('registerError');if(!e.currentTarget.reportValidity())return;const data=new FormData(e.currentTarget),firstName=String(data.get('firstName')).trim(),lastName=String(data.get('lastName')).trim(),name=`${firstName} ${lastName}`,email=String(data.get('email')).trim().toLowerCase(),password=String(data.get('password'));if(password!==String(data.get('confirmPassword'))){showAuthError('registerError','รหัสผ่านและการยืนยันรหัสผ่านไม่ตรงกัน');return}const users=readAuthUsers();if(users.some(item=>item.email===email)){showAuthError('registerError','อีเมลนี้มีบัญชีแล้ว กรุณาเข้าสู่ระบบ');return}try{const salt=crypto.getRandomValues(new Uint8Array(16)),passwordHash=await hashDemoPassword(password,salt),user={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),name,firstName,lastName,email,salt:encodeBytes(salt),passwordHash};localStorage.setItem(AUTH_USERS_KEY,JSON.stringify([...users,user]));sessionStorage.setItem('carbonlens-auth-session',user.id);localStorage.setItem(`carbonlens-onboarding-pending-${user.id}`,'true');enterDemo(true);showToast('สร้างบัญชีแล้ว กรุณากรอกข้อมูลแปลงก่อนเริ่มใช้งาน')}catch(error){showAuthError('registerError',error.message||'ไม่สามารถสร้างบัญชีได้')}});
