const dialog=document.getElementById('projectDialog'), projectForm=dialog.querySelector('form');let editingId=null;
function renderProjects(){const query=(document.getElementById('projectSearch')?.value||'').trim().toLocaleLowerCase('th');const status=document.getElementById('statusFilter')?.value||'';const province=document.getElementById('provinceFilter')?.value||'';const filtered=projects.filter(p=>(!query||`${p.name} ${p.province} ${p.district}`.toLocaleLowerCase('th').includes(query))&&(!status||p.status===status)&&(!province||p.province===province));const rows=document.getElementById('projectRows');if(!rows)return;rows.innerHTML=filtered.map((p,i)=>`<tr><td><div class="project-cell"><span class="project-thumb ${['thumb-forest','thumb-sage','thumb-olive','thumb-mint'][i%4]}">♧</span><span><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.parcelName||'ชื่อแปลงยังไม่ระบุ')} · ${escapeHtml(p.province)} · อ.${escapeHtml(p.district||'—')}</small></span></div></td><td>${Number(p.area||0).toLocaleString('th-TH')} ไร่</td><td>${Number(p.plots||1)} แปลง</td><td><span class="badge ${p.status==='กำลังดำเนินการ'?'badge-green':p.status==='รอตรวจสอบ'?'badge-yellow':'badge-blue'}"><i></i>${escapeHtml(p.status)}</span></td><td>${escapeHtml(p.updated||'วันนี้')}</td><td><div class="row-actions"><button class="row-action" data-action="view" data-id="${p.id}">ดู</button><button class="row-action" data-action="edit" data-id="${p.id}">แก้ไข</button><button class="row-action danger" data-action="delete" data-id="${p.id}">ลบ</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty-row">ไม่พบรายการที่ตรงกับการค้นหา</td></tr>';document.getElementById('resultCount').textContent=`${filtered.length} รายการ`;document.querySelectorAll('.nav-count').forEach(el=>el.textContent=String(projects.reduce((sum,p)=>sum+Number(p.plots||1),0)))}
function renderDashboard(){const cards=document.querySelectorAll('#page-dashboard .stats-grid .stat-card');if(cards.length){cards[0].querySelector('.stat-value').innerHTML=`${String(projects.length).padStart(2,'0')} <small>โครงการ</small>`;const totalArea=projects.reduce((n,p)=>n+Number(p.area||0),0);cards[1].querySelector('.stat-value').innerHTML=`${totalArea.toLocaleString('th-TH')} <small>ไร่</small>`;cards[1].querySelector('.mini-pill').textContent=`${projects.reduce((n,p)=>n+Number(p.plots||1),0)} แปลง`;const active=projects.filter(p=>p.status==='กำลังดำเนินการ'||p.status==='รอตรวจสอบ').length;cards[2].querySelector('.stat-top span').textContent='โครงการระหว่างประเมิน';cards[2].querySelector('.stat-value').innerHTML=`${active} <small>โครงการ</small>`;cards[2].querySelector('.stat-foot').innerHTML='<span class="status-dot"></span> ยังไม่ใช่ผลประเมินคาร์บอน';cards[3].querySelector('.stat-value').innerHTML=`${projects.reduce((n,p)=>n+Number(p.plots||1),0)} <small>แปลง</small>`;cards[3].querySelector('.stat-foot').innerHTML=`<span class="muted">${projects.length} โครงการ · บันทึกในเครื่อง</span>`}const body=document.querySelector('#page-dashboard .projects-panel tbody');if(body)body.innerHTML=projects.slice(0,3).map((p,i)=>`<tr><td><div class="project-cell"><span class="project-thumb ${['thumb-forest','thumb-sage','thumb-olive'][i%3]}">♧</span><span><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.province)} · ${escapeHtml(p.updated||'วันนี้')}</small></span></div></td><td>${Number(p.area||0).toLocaleString('th-TH')} ไร่</td><td><span class="badge ${p.status==='กำลังดำเนินการ'?'badge-green':p.status==='รอตรวจสอบ'?'badge-yellow':'badge-blue'}"><i></i>${escapeHtml(p.status)}</span></td><td><div class="progress-cell"><div class="progress"><i style="width:${p.status==='กำลังดำเนินการ'?68:p.status==='รอตรวจสอบ'?42:24}%"></i></div><small>${p.status==='กำลังดำเนินการ'?'68':p.status==='รอตรวจสอบ'?'42':'24'}%</small></div></td><td><button class="row-more" data-goto="projects">···</button></td></tr>`).join('');const areaChart=document.getElementById('areaChart');if(areaChart){const max=Math.max(1,...projects.map(p=>Number(p.area)||0));areaChart.innerHTML=projects.length?projects.slice(0,5).map(p=>`<div class="area-bar-row"><span title="${escapeHtml(p.name)}">${escapeHtml(p.name)}</span><div><i style="width:${Math.max(2,(Number(p.area)||0)/max*100)}%"></i></div><b>${Number(p.area||0).toLocaleString('th-TH')}</b></div>`).join(''):'<span class="muted">ยังไม่มีโครงการ</span>'}const statusChart=document.getElementById('statusChart');if(statusChart){const order=['กำลังดำเนินการ','รอตรวจสอบ','เตรียมข้อมูล'];const colors=['#6d9d70','#d4b15e','#8da9c8'];statusChart.innerHTML=order.map((s,i)=>`<div class="status-bar-row"><span><i style="background:${colors[i]}"></i>${s}</span><b>${projects.filter(p=>p.status===s).length}</b></div>`).join('')}renderReportPreview()}
function renderReportPreview(){const report=document.getElementById('page-reports');if(!report)return;const project=projects[0];let section=document.getElementById('reportPreview');if(!section){section=document.createElement('section');section.id='reportPreview';section.className='panel report-preview';report.querySelector('.report-hero').after(section)}section.innerHTML=`<div class="panel-heading"><div><h2>ตัวอย่างเนื้อหารายงาน · ${escapeHtml(project?.name||'ยังไม่มีโครงการ')}</h2><p>สรุปพื้นที่ แผนที่ ข้อมูลวิเคราะห์ และรายการที่ยังขาด</p></div><span class="estimate-tag">DEMO</span></div><div class="report-preview-grid"><div class="report-map-placeholder"><span>⌖</span><b>แผนที่ขอบเขต</b><small>${project?.boundary?'มี GeoJSON ที่บันทึกในเบราว์เซอร์':'รอเพิ่มและยืนยัน Polygon'}</small></div><div class="report-fields"><div><span>พื้นที่รวม</span><b>${project?.boundary?`${Number(project.area).toLocaleString('th-TH')} ไร่`:'รอข้อมูลเพิ่มเติม'}</b></div><div><span>ข้อมูลดาวเทียม</span><b>Sentinel-2 · DEMO เท่านั้น</b></div><div><span>ผล AI</span><b>ยังไม่มี Model API</b></div><div><span>ระเบียบวิธี</span><b>ยังไม่ได้เลือก/ยืนยัน T-VER</b></div><div><span>เครดิต / มูลค่า</span><b>รอข้อมูลเพิ่มเติม · ไม่มีผลคำนวณ</b></div><div><span>ต้องตรวจภาคสนาม</span><b>สิทธิ์พื้นที่, ชนิดไม้, ชีวมวล, ภาพถ่าย</b></div></div></div>`}
document.getElementById('projectSearch').addEventListener('input',renderProjects);document.getElementById('statusFilter').addEventListener('change',renderProjects);document.getElementById('provinceFilter').addEventListener('change',renderProjects);
function openProjectForm(project=null){editingId=project?.id||null;projectForm.reset();document.getElementById('projectDialogTitle').textContent=project?'แก้ไขข้อมูลแปลง':'กรอกข้อมูลแปลงใหม่';document.getElementById('createProject').textContent='บันทึกข้อมูลแปลง';if(project){document.getElementById('newProjectName').value=project.name||'';document.getElementById('newProjectParcelName').value=project.parcelName||'';document.getElementById('newProjectProvince').value=project.province||'';document.getElementById('newProjectDistrict').value=project.district||'';document.getElementById('newProjectVillage').value=project.village||'';document.getElementById('newProjectManager').value=project.manager||'';document.getElementById('newProjectForestType').value=project.forestType||'';document.getElementById('newProjectArea').value=project.area||'';document.getElementById('newProjectPlots').value=project.plots||1;document.getElementById('newProjectLandStatus').value=project.landStatus||'';document.getElementById('newProjectLandEvidence').value=project.landEvidence||'';document.getElementById('newProjectActivity').value=project.projectActivity||'';document.getElementById('newProjectPlantingYear').value=project.plantingYear||'';document.getElementById('newProjectDominantSpecies').value=project.dominantSpecies||'';document.getElementById('newProjectForestCondition').value=project.forestCondition||'';document.getElementById('newProjectFieldEvidence').value=project.fieldEvidence||'';document.getElementById('newProjectMethodology').value=project.methodology||'';document.getElementById('newProjectBaselineHistory').value=project.baselineHistory||'';document.getElementById('newProjectInventoryNotes').value=project.inventoryNotes||'';document.getElementById('newProjectDescription').value=project.description||'';document.getElementById('newProjectStatus').value=project.status||'เตรียมข้อมูล'}refreshAddressOptions();dialog.showModal()}
document.getElementById('addProject').addEventListener('click',()=>openProjectForm());
document.getElementById('dashboardAddProject').addEventListener('click',()=>guestMode?showVisitorPrompt():openProjectForm());
document.getElementById('createProject').addEventListener('click',e=>{e.preventDefault();const province=addressProvince(),district=addressDistrict();provinceInput.setCustomValidity(province?'':'กรุณาเลือกจังหวัดจากรายการ');districtInput.setCustomValidity(districtInput.value&&!district?'กรุณาเลือกอำเภอ/เขตจากรายการของจังหวัดที่เลือก':'');subdistrictInput.setCustomValidity(subdistrictInput.value&&!district?.subdistricts.some(place=>place.name===subdistrictInput.value)?'กรุณาเลือกตำบล/แขวงจากรายการของอำเภอที่เลือก':'');if(!projectForm.reportValidity())return;const data={name:document.getElementById('newProjectName').value.trim(),parcelName:document.getElementById('newProjectParcelName').value.trim(),province:document.getElementById('newProjectProvince').value,district:document.getElementById('newProjectDistrict').value.trim(),village:document.getElementById('newProjectVillage').value.trim(),manager:document.getElementById('newProjectManager').value.trim(),forestType:document.getElementById('newProjectForestType').value,area:Number(document.getElementById('newProjectArea').value)||0,plots:Number(document.getElementById('newProjectPlots').value)||1,landStatus:document.getElementById('newProjectLandStatus').value.trim(),landEvidence:document.getElementById('newProjectLandEvidence').value.trim(),projectActivity:document.getElementById('newProjectActivity').value,plantingYear:Number(document.getElementById('newProjectPlantingYear').value)||0,dominantSpecies:document.getElementById('newProjectDominantSpecies').value.trim(),forestCondition:document.getElementById('newProjectForestCondition').value.trim(),fieldEvidence:document.getElementById('newProjectFieldEvidence').value.trim(),methodology:document.getElementById('newProjectMethodology').value.trim(),baselineHistory:document.getElementById('newProjectBaselineHistory').value.trim(),inventoryNotes:document.getElementById('newProjectInventoryNotes').value.trim(),description:document.getElementById('newProjectDescription').value.trim(),status:document.getElementById('newProjectStatus').value,updated:'วันนี้'};if(editingId){projects=projects.map(p=>p.id===editingId?{...p,...data}:p);showToast('บันทึกข้อมูลแปลงแล้ว')}else{projects.unshift({id:`p-${Date.now()}-${Math.floor(Math.random()*10000)}`, ...data});showToast('บันทึกข้อมูลแปลงแล้ว')}dialog.close();saveProjects();if(onboardingRequired&&!editingId){onboardingRequired=false;localStorage.removeItem(`carbonlens-onboarding-pending-${activeUserId}`);go('dashboard')}});
let viewingProjectId=null;
document.getElementById('projectRows').addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn)return;const project=projects.find(p=>p.id===btn.dataset.id);if(!project)return;if(btn.dataset.action==='edit')openProjectForm(project);if(btn.dataset.action==='view'){viewingProjectId=project.id;document.getElementById('detailsName').textContent=project.name;document.getElementById('detailsBody').innerHTML=`<div><span>ชื่อแปลง</span><b>${escapeHtml(project.parcelName||'ยังไม่ระบุ')}</b></div><div><span>ที่ตั้ง</span><b>${escapeHtml(project.village||'')}${project.village?' · ':''}${escapeHtml(project.district||'—')}, ${escapeHtml(project.province)}</b></div><div><span>พื้นที่ป่า</span><b>${escapeHtml(project.forestType||'ยังไม่ระบุ')}</b></div><div><span>พื้นที่โดยประมาณ</span><b>${Number(project.area||0).toLocaleString('th-TH')} ไร่ · ${Number(project.plots||1)} แปลง</b></div><div><span>สิทธิ/การใช้พื้นที่</span><b>${escapeHtml(project.landStatus||'รอตรวจสอบ')}</b></div><div><span>หลักฐานสิทธิพื้นที่</span><b>${escapeHtml(project.landEvidence||'ยังไม่ระบุ')}</b></div><div><span>กิจกรรมโครงการ</span><b>${escapeHtml(project.projectActivity||'ยังไม่ระบุ')}</b></div><div><span>ปีเริ่มกิจกรรม</span><b>${escapeHtml(project.plantingYear||'ยังไม่ระบุ')}</b></div><div><span>ชนิดไม้หลัก</span><b>${escapeHtml(project.dominantSpecies||'ยังไม่ระบุ')}</b></div><div><span>สภาพป่าปัจจุบัน</span><b>${escapeHtml(project.forestCondition||'ยังไม่ระบุ')}</b></div><div><span>บันทึกภาคสนาม</span><b>${escapeHtml(project.fieldEvidence||'ยังไม่ระบุ')}</b></div><div><span>ผู้รับผิดชอบ</span><b>${escapeHtml(project.manager||'ยังไม่ระบุ')}</b></div><div><span>สถานะ</span><b>${escapeHtml(project.status)}</b></div><div><span>รายละเอียด</span><b>${escapeHtml(project.description||'ยังไม่มีรายละเอียด')}</b></div><div><span>ขอบเขต</span><b>${project.boundary?'มี GeoJSON ในเบราว์เซอร์':'ยังไม่มี Polygon'}</b></div>`;document.getElementById('projectDetailsDialog').showModal()}if(btn.dataset.action==='delete'&&confirm(`ลบโครงการ “${project.name}” จากข้อมูลในเบราว์เซอร์นี้หรือไม่?`)){projects=projects.filter(p=>p.id!==project.id);saveProjects();showToast('ลบโครงการแล้ว')}});
document.getElementById('closeProjectDetails').addEventListener('click',()=>document.getElementById('projectDetailsDialog').close());
document.getElementById('detailsEdit').addEventListener('click',()=>{const project=projects.find(p=>p.id===viewingProjectId);document.getElementById('projectDetailsDialog').close();if(project)openProjectForm(project)});
document.getElementById('detailsMap').addEventListener('click',()=>{const project=projects.find(p=>p.id===viewingProjectId);document.getElementById('projectDetailsDialog').close();if(project){document.getElementById('parcelProject').value=project.id;go('map');setTimeout(()=>document.getElementById('parcelProject').dispatchEvent(new Event('change')),100)}});
renderProjects();renderDashboard();renderParcelProjects();document.querySelectorAll('.report-card-foot span').forEach(el=>el.textContent=el.textContent.replace('PDF','TXT'));
const indexPanel=document.createElement('section');indexPanel.className='panel indices-panel';indexPanel.innerHTML='<div class="panel-heading"><div><h2>ดัชนีพืชพรรณ</h2><p>ค่าทั้งหมดเป็นตัวอย่าง เว้นแต่เชื่อมข้อมูลจริง</p></div><span class="mock-tag">DEMO VALUES</span></div><div class="sat-index-cards"><div><span>NDVI</span><b>0.68</b><small>ค่าจำลอง</small></div><div><span>EVI</span><b>—</b><small>รอข้อมูล Sentinel-2</small></div><div><span>GNDVI</span><b>—</b><small>รอข้อมูล Sentinel-2</small></div></div><div class="sat-meta"><span><small>เมฆปกคลุม</small><b>รอข้อมูล Sentinel-2</b></span><span><small>แถบคลื่น</small><b>รอ preprocessing จริง</b></span><span><small>ML pipeline</small><b>ยังไม่เชื่อมต่อ</b></span></div>';
document.getElementById('page-satellite').querySelector('.sat-bottom').before(indexPanel);
const paperNote=document.createElement('small');paperNote.className='reference-title';paperNote.textContent='แนวคิดอ้างอิง: “Advancing forest carbon stocks’ mapping using a hierarchical approach with machine learning and satellite imagery” (2024)';document.querySelector('#page-assessment .model-note h2').after(paperNote);
const creditStates=document.createElement('div');creditStates.className='status-summary';creditStates.innerHTML='<span class="potential">มีศักยภาพ · ยังไม่ประเมิน</span><span class="review">ต้องตรวจสอบเพิ่มเติม · ยังไม่ประเมิน</span><span class="insufficient">ข้อมูลไม่เพียงพอ · สถานะปัจจุบัน</span>';document.querySelector('#page-carbon .carbon-status-grid').after(creditStates);
