// Real geographic polygon area from WGS84 coordinates (spherical geodesic; demo quality).
let mapInstance,drawnItems,polygonLayer;
function polygonGeoJSON(layer){return layer?layer.toGeoJSON():null}
function updateBoundaryInfo(){const area=polygonLayer?window.CarbonLensGeometry.geodesicArea(polygonLayer.getLatLngs()[0]):0;const {rai,hectares}=window.CarbonLensGeometry.areaUnits(area);document.getElementById('areaValue').innerHTML=polygonLayer?`${rai.toLocaleString('th-TH',{maximumFractionDigits:2})} <small>ไร่</small>`:'— <small>ไร่</small>';document.getElementById('areaMeasures').textContent=polygonLayer?`${hectares.toLocaleString('th-TH',{maximumFractionDigits:3})} เฮกตาร์ · ${area.toLocaleString('th-TH',{maximumFractionDigits:1})} ตร.ม.`:'— เฮกตาร์ · — ตร.ม.';if(!polygonLayer){document.getElementById('coordinates').textContent='ยังไม่มีขอบเขต';document.getElementById('pointCount').textContent='ยังไม่มี Polygon';return}const geo=polygonGeoJSON(polygonLayer),coords=geo.geometry.coordinates[0];document.getElementById('coordinates').textContent=coords.map((c,i)=>`${i+1}. ${c[1].toFixed(6)}, ${c[0].toFixed(6)}`).join('\n');document.getElementById('pointCount').textContent=`${Math.max(0,coords.length-1)} จุด · GeoJSON`}
function initMap(){if(mapInstance){mapInstance.invalidateSize();return}if(!window.L){showToast('โหลดไลบรารีแผนที่ไม่สำเร็จ ตรวจสอบอินเทอร์เน็ตแล้วเปิดหน้านี้ใหม่');return}mapInstance=L.map('leafletMap').setView([18.55,98.35],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(mapInstance);drawnItems=new L.FeatureGroup().addTo(mapInstance);mapInstance.addControl(new L.Control.Draw({position:'topleft',draw:{polygon:{allowIntersection:false,showArea:true,shapeOptions:{color:'#28744f',fillColor:'#8fb982',fillOpacity:.25}},rectangle:false,circle:false,circlemarker:false,polyline:false,marker:false},edit:{featureGroup:drawnItems,remove:true}}));mapInstance.on(L.Draw.Event.CREATED,e=>{drawnItems.clearLayers();polygonLayer=e.layer;drawnItems.addLayer(polygonLayer);updateBoundaryInfo()});mapInstance.on(L.Draw.Event.EDITED,updateBoundaryInfo);mapInstance.on(L.Draw.Event.DELETED,()=>{polygonLayer=null;updateBoundaryInfo()});const saved=projects.find(p=>p.id===document.getElementById('parcelProject').value)?.boundary;if(saved){const imported=L.geoJSON(saved).getLayers()[0];if(imported){polygonLayer=imported;drawnItems.addLayer(imported);mapInstance.fitBounds(imported.getBounds());updateBoundaryInfo()}}setTimeout(()=>mapInstance.invalidateSize(),120)}
document.getElementById('locateThailand').addEventListener('click',()=>{initMap();if(mapInstance)mapInstance.setView([15.87,100.99],6)});
const DEMO_PLACES=[{name:'แม่แจ่ม, เชียงใหม่',lat:18.499,lng:98.365},{name:'เมืองเชียงใหม่',lat:18.7883,lng:98.9853},{name:'ดอยสุเทพ, เชียงใหม่',lat:18.8058,lng:98.9214},{name:'อำเภอลี้, ลำพูน',lat:17.802,lng:98.95},{name:'ห้วยน้ำดัง, เชียงใหม่',lat:19.302,lng:98.607},{name:'ประเทศไทย',lat:15.87,lng:100.99}];
document.getElementById('searchPlace').addEventListener('click',()=>{initMap();if(!mapInstance)return;const query=document.getElementById('placeSearch').value.trim();if(!query){showToast('กรอกชื่อสถานที่หรือพิกัดก่อนค้นหา');return}const match=query.match(/^\s*(-?\d+(?:\.\d+)?)\s*[, ]\s*(-?\d+(?:\.\d+)?)\s*$/);if(match){const lat=Number(match[1]),lng=Number(match[2]);if(lat<-90||lat>90||lng<-180||lng>180){showToast('พิกัดไม่ถูกต้อง');return}mapInstance.setView([lat,lng],14);L.marker([lat,lng]).addTo(mapInstance).bindPopup(`พิกัด ${lat.toFixed(6)}, ${lng.toFixed(6)}`).openPopup();return}const place=DEMO_PLACES.find(item=>item.name.toLocaleLowerCase('th').includes(query.toLocaleLowerCase('th'))||query.toLocaleLowerCase('th').includes(item.name.split(',')[0].toLocaleLowerCase('th')));if(!place){showToast('ไม่พบสถานที่ในตัวอย่าง ลองค้น “แม่แจ่ม”, “เชียงใหม่” หรือใส่พิกัด');return}mapInstance.setView([place.lat,place.lng],12);L.marker([place.lat,place.lng]).addTo(mapInstance).bindPopup(`${escapeHtml(place.name)} · ตำแหน่งตัวอย่าง`).openPopup()});
document.getElementById('parcelProject').addEventListener('change',()=>{if(mapInstance){drawnItems.clearLayers();polygonLayer=null;const saved=projects.find(p=>p.id===document.getElementById('parcelProject').value)?.boundary;if(saved){polygonLayer=L.geoJSON(saved).getLayers()[0];drawnItems.addLayer(polygonLayer);mapInstance.fitBounds(polygonLayer.getBounds())}updateBoundaryInfo()}});
document.getElementById('saveBoundary').addEventListener('click',()=>{if(!polygonLayer){showToast('วาด Polygon อย่างน้อย 3 จุดก่อนบันทึก');go('map');return}const active=projects.find(p=>p.id===document.getElementById('parcelProject').value);if(!active){showToast('เลือกโครงการก่อนบันทึก');return}active.boundary=polygonGeoJSON(polygonLayer);active.parcelName=document.getElementById('parcelName').value;active.area=window.CarbonLensGeometry.areaUnits(window.CarbonLensGeometry.geodesicArea(polygonLayer.getLatLngs()[0])).rai;active.plots=Math.max(1,Number(active.plots)||1);active.updated='วันนี้';saveProjects();showToast('บันทึก GeoJSON และพื้นที่ในเบราว์เซอร์นี้แล้ว')});
document.getElementById('uploadBoundary').addEventListener('click',()=>document.getElementById('fileInput').click());document.getElementById('fileInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!window.L)throw new Error('map');const layer=L.geoJSON(data).getLayers().find(x=>x instanceof L.Polygon);if(!layer)throw new Error('polygon');initMap();drawnItems.clearLayers();polygonLayer=layer;drawnItems.addLayer(layer);mapInstance.fitBounds(layer.getBounds());updateBoundaryInfo();showToast('นำเข้า GeoJSON แล้ว')}catch{showToast('อ่านไฟล์ไม่ได้ ต้องเป็น GeoJSON ที่มี Polygon');}e.target.value=''});
document.getElementById('exportGeoJSON').addEventListener('click',()=>{if(!polygonLayer){showToast('ยังไม่มีขอบเขตสำหรับส่งออก');return}download('carbonlens-boundary-demo.geojson',JSON.stringify(polygonGeoJSON(polygonLayer),null,2),'application/geo+json');showToast('ส่งออก GeoJSON แล้ว')});

function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.getElementById('downloadSummary').addEventListener('click',()=>{const text=`CARBONLENS · สรุปโครงการ (DEMO)\n\nโครงการ: ${projects[0]?.name||'—'}\nพื้นที่: ${projects[0]?.area||'รอข้อมูลเพิ่มเติม'} ไร่ (ข้อมูลตัวอย่าง)\nผล AI: ยังไม่มีโมเดลหรือผลทำนายจริง\nเครดิตคาร์บอน: รอข้อมูลเพิ่มเติม — ไม่มีผลคำนวณ\n\nหมายเหตุ: ไม่ใช่ข้อมูลดาวเทียมจริง ไม่ใช่ผลคำนวณหรือเครดิตรับรอง`;download('carbonlens-project-summary-demo.txt',text);showToast('ดาวน์โหลดสรุปตัวอย่างแล้ว')});
document.querySelectorAll('[data-report]').forEach(button=>button.addEventListener('click',()=>{download(`carbonlens-${button.dataset.report}-demo.txt`,`${button.dataset.report}\nCarbonLens · DEMO\n\nรอเชื่อมข้อมูลและบริการจริง\nไม่ใช่รายงานเพื่อยื่นรับรอง`);showToast('ดาวน์โหลดไฟล์ตัวอย่างแล้ว (TXT)')}));
document.getElementById('generateReport').addEventListener('click',()=>{showToast('เปิดหน้าพิมพ์เพื่อบันทึกเป็น PDF ได้');setTimeout(()=>window.print(),300)});
document.getElementById('exportCsv').addEventListener('click',()=>{const header=['ชื่อโครงการ','จังหวัด','อำเภอ','ประเภทป่า','พื้นที่ไร่','สถานะ','หมายเหตุ'];const rows=projects.map(p=>[p.name,p.province,p.district,p.forestType,p.area,p.status,'ข้อมูลตัวอย่าง']);download('carbonlens-projects-demo.csv','\ufeff'+[header,...rows].map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n'),'text/csv;charset=utf-8');showToast('ดาวน์โหลด CSV (เปิดด้วย Excel ได้) แล้ว')});
document.getElementById('exportChecklist').addEventListener('click',()=>{const rows=[['หมวด','รายการตรวจสอบ','สถานะ'],...Array.from(document.querySelectorAll('.check-row')).map(row=>[row.closest('.field-group').querySelector('h2').textContent,row.querySelector('b').textContent,row.dataset.verificationState||'ยังไม่ตรวจสอบ'])];download('carbonlens-field-checklist-demo.csv','\ufeff'+rows.map(row=>row.map(v=>`"${v.replaceAll('"','""')}"`).join(',')).join('\r\n'),'text/csv;charset=utf-8');showToast('ดาวน์โหลดรายการตรวจสอบตัวอย่างแล้ว')});
document.getElementById('refreshSatellite').addEventListener('click',()=>showToast('Sentinel-2, cloud coverage, NDVI, EVI และ GNDVI ยังรอ API จริง'));
document.getElementById('runAssessment').addEventListener('click',()=>{showToast('Workflow ตัวอย่างเท่านั้น: ยังไม่มี Model API หรือผลทำนาย');document.getElementById('aiResult').textContent='รอชุดข้อมูลฝึกและ Model API — ไม่มีผลทำนายใน Demo นี้'});
document.querySelectorAll('.check-row input').forEach(input=>input.addEventListener('change',()=>input.closest('.check-row').classList.toggle('checked',input.checked)));
document.querySelectorAll('.collapse-btn').forEach(button=>button.addEventListener('click',()=>{const list=button.closest('.field-group').querySelector('.checklist');list.hidden=!list.hidden;button.textContent=list.hidden?'⌄':'⌃'}));
document.querySelectorAll('.attach-btn').forEach(button=>button.addEventListener('click',()=>showToast('ส่วนแนบไฟล์จะแสดงเมื่อเชื่อมต่อ backend')));
document.querySelectorAll('.show-more').forEach(button=>button.addEventListener('click',()=>showToast('รายการตัวอย่างแสดงเท่าที่มีในต้นแบบ')));
const verificationStates=['ยังไม่ตรวจสอบ','รอตรวจสอบ','ตรวจสอบแล้ว','ต้องแก้ไขข้อมูล'];
function addChecklistState(row,state=row.classList.contains('checked')?'ตรวจสอบแล้ว':'รอตรวจสอบ'){row.dataset.verificationState=state;let control=row.querySelector('.verification-state');if(!control){control=document.createElement('button');control.type='button';control.className='verification-state';row.append(control);control.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const item=e.currentTarget.closest('.check-row');const next=(verificationStates.indexOf(item.dataset.verificationState)+1)%verificationStates.length;addChecklistState(item,verificationStates[next]);const checkbox=item.querySelector('input');checkbox.checked=verificationStates[next]==='ตรวจสอบแล้ว';item.classList.toggle('checked',checkbox.checked);updateChecklistCounts()})}control.textContent=state;control.dataset.state=state}
function updateChecklistCounts(){const rows=[...document.querySelectorAll('.check-row')];const done=rows.filter(row=>row.dataset.verificationState==='ตรวจสอบแล้ว').length;const summary=document.querySelectorAll('.field-summary>div:not(.field-progress) b');if(summary.length>=3){summary[0].textContent=`${rows.length} รายการ`;summary[1].textContent=`${done} รายการ`;summary[2].textContent=`${rows.length-done} รายการ`}const progress=document.querySelector('.field-progress .progress i');if(progress)progress.style.width=`${rows.length?Math.round(done/rows.length*100):0}%`;const label=document.querySelector('.field-progress small');if(label)label.textContent=`ความคืบหน้า ${rows.length?Math.round(done/rows.length*100):0}%`;document.querySelectorAll('.field-group').forEach(group=>{const items=[...group.querySelectorAll('.check-row')],count=items.filter(row=>row.dataset.verificationState==='ตรวจสอบแล้ว').length;const badge=group.querySelector('.group-count');if(badge)badge.textContent=`${count}/${items.length}`})}
document.querySelectorAll('.check-row').forEach(row=>addChecklistState(row));
const checklistGroups=document.querySelectorAll('.field-group');
if(checklistGroups[1]){checklistGroups[1].querySelector('.checklist').insertAdjacentHTML('beforeend','<label class="check-row"><input type="checkbox"><span class="custom-check"></span><span><b>ตรวจสภาพการฟื้นตัวและเรือนยอด</b><small>บันทึกสภาพพื้นที่และหลักฐานประกอบ</small></span></label>');addChecklistState(checklistGroups[1].querySelectorAll('.check-row')[4],'รอตรวจสอบ');checklistGroups[1].querySelector('.show-more')?.remove()}
if(checklistGroups[2]){checklistGroups[2].querySelector('.checklist').insertAdjacentHTML('beforeend','<label class="check-row"><input type="checkbox"><span class="custom-check"></span><span><b>ยืนยันแผนติดตามและการรายงาน</b><small>ระบุรอบเวลา ผู้รับผิดชอบ และวิธีจัดเก็บหลักฐาน</small></span></label>');addChecklistState(checklistGroups[2].querySelectorAll('.check-row')[2],'รอตรวจสอบ')}
document.querySelectorAll('.check-row input').forEach(input=>input.addEventListener('change',()=>{const row=input.closest('.check-row');row.classList.toggle('checked',input.checked);addChecklistState(row,input.checked?'ตรวจสอบแล้ว':'ยังไม่ตรวจสอบ');updateChecklistCounts()}));
updateChecklistCounts();
